// Fixes: chatty→BFF aggregation; retry storm→backoff+jitter+circuit breaker+budget.
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class MicroservicesAntiPatternsDemo {
    private static final Logger log = Logger.getLogger("AP");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        DownstreamService account = new DownstreamService("account", false);
        DownstreamService card = new DownstreamService("card", false);
        DownstreamService rewards = new DownstreamService("rewards", true); // failing

        // FIX chatty services: one aggregated BFF call instead of 3 client round trips.
        log.info("=== fix chatty services: BFF aggregation (parallel fan-out) ===");
        DashboardBff bff = new DashboardBff(account, card, rewards);
        String dashboard = bff.getDashboard("SAV2001");
        log.info(() -> "Dashboard (one client call): " + dashboard);

        // FIX retry storm: backoff + jitter + circuit breaker + retry budget.
        log.info("=== fix retry storm: backoff + jitter + circuit breaker + budget ===");
        CircuitBreaker breaker = new CircuitBreaker(3);
        ResilientCaller caller = new ResilientCaller(3, 100, breaker, 20);
        for (int i = 1; i <= 5; i++) {
                String result = caller.call("rewards", () -> { rewards.callSync();
                return "points=1200"; });
            log.info(() -> "Call result: " + result);
        }
    }
}

// ─── bff/DashboardBff.java (aggregation layer — fixes chatty services) ───
class DashboardBff {
    private static final Logger log = Logger.getLogger("AP");
    private final DownstreamService account, card, rewards;
    private final ExecutorService pool = Executors.newFixedThreadPool(3);
    DashboardBff(DownstreamService account, DownstreamService card, DownstreamService rewards) {
            this.account = account;
            this.card = card
            this.rewards = rewards;
    }
    String getDashboard(String customerId) throws Exception {
        // Fan out concurrently server-side; client makes ONE call.
        Future<String> a = pool.submit(() -> safe(account));
        Future<String> c = pool.submit(() -> safe(card));
        Future<String> r = pool.submit(() -> safe(rewards));
        String combined = "account=" + a.get() + ", card=" + c.get() + ", rewards=" + r.get();
        log.info(() -> "BFF aggregated 3 services into 1 response for " + customerId);
        pool.shutdown();
        return combined;
    }
    private String safe(DownstreamService svc) {
            try { svc.callSync();
            return "ok"; } catch (RuntimeException e) { return "unavailable"; }
    }
}

// ─── resilience/ResilientCaller.java (backoff + jitter + budget + breaker) ───
class ResilientCaller {
    private static final Logger log = Logger.getLogger("AP");
    private final int maxAttempts; private final long baseDelayMs;
    private final CircuitBreaker breaker; private final int budgetPerMin;
    private int retriesUsed = 0;
    private final Random rnd = new Random(42);
    ResilientCaller(int maxAttempts, long baseDelayMs, CircuitBreaker breaker, int budgetPerMin) {
            this.maxAttempts = maxAttempts;
            this.baseDelayMs = baseDelayMs;
            this.breaker = breaker;
            this.budgetPerMin = budgetPerMin;
    }
    String call(String dep, java.util.function.Supplier<String> action) {
            if (!breaker.allow()) { log.warning(() -> "Circuit OPEN for " + dep + " — fail fast");
            return "fallback"; }
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                String r = action.get();
                breaker.onSuccess();
                return r;
            } catch (RuntimeException e) {
                breaker.onFailure();
                    if (retriesUsed >= budgetPerMin) { log.warning("Retry budget exhausted — stop");
                    return "fallback"; }
                    if (attempt == maxAttempts) { log.warning(() -> dep + " failed after " + maxAttempts + " attempts");
                    return "fallback"; }
                retriesUsed++;
                // Exponential backoff with jitter: base * 2^attempt + random spread.
                long backoff = (long) (baseDelayMs * Math.pow(2, attempt)) + rnd.nextInt(50);
                log.info(() -> "Retry " + dep + " attempt " + attempt + " after " + backoff
                        + "ms (backoff+jitter, no thundering herd)");
            }
        }
        return "fallback";
    }
}

// ─── resilience/CircuitBreaker.java ───
class CircuitBreaker {
    private static final Logger log = Logger.getLogger("AP");
    private final int threshold; private int failures = 0; private boolean open = false;
    CircuitBreaker(int threshold) { this.threshold = threshold; }
    boolean allow() { return !open; }
    void onSuccess() { failures = 0; }
        void onFailure() { if (++failures >= threshold) { open = true;
        log.severe("Circuit OPENED"); } }
}

// ─── downstream/DownstreamService.java ───
class DownstreamService {
    private final String name; private final boolean failing;
        DownstreamService(String name, boolean failing) { this.name = name;
        this.failing = failing; }
    void callSync() { if (failing) throw new RuntimeException(name + " failing"); }
}

